edgecode='''from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r,c) in seen:
                continue
            q = deque([(r,c)]); seen.add((r,c)); comp=[]
            while q:
                rr,cc=q.popleft(); comp.append((rr,cc))
                for nr,nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            touches = {side for rr,cc in comp for side,cond in (("top",rr==0),("bottom",rr==h-1),("left",cc==0),("right",cc==w-1)) if cond}
            fill = not touches
            if len(touches) == 1:
                r0=min(rr for rr,cc in comp); r1=max(rr for rr,cc in comp)
                c0=min(cc for rr,cc in comp); c1=max(cc for rr,cc in comp)
                rectangular = len(comp) == (r1-r0+1)*(c1-c0+1)
                side=next(iter(touches))
                walls=[]
                if side != "top": walls.append(all(grid[r0-1][cc] != background for cc in range(c0,c1+1)) if r0>0 else False)
                if side != "bottom": walls.append(all(grid[r1+1][cc] != background for cc in range(c0,c1+1)) if r1<h-1 else False)
                if side != "left": walls.append(all(grid[rr][c0-1] != background for rr in range(r0,r1+1)) if c0>0 else False)
                if side != "right": walls.append(all(grid[rr][c1+1] != background for rr in range(r0,r1+1)) if c1<w-1 else False)
                fill = rectangular and all(walls)
            if fill:
                for rr,cc in comp: out[rr][cc]=4
    return out
'''
